// Insert a "Shorts only" chip after the "Unwatched" chip (2nd chip)
const unwatchedChip = element.closest('yt-chip-cloud-chip-renderer');
if (!unwatchedChip) return;

// Check if we already added the Shorts chip
if (unwatchedChip.nextElementSibling && unwatchedChip.nextElementSibling.getAttribute('data-custom-shorts-chip') === 'true') return;

const newChip = document.createElement('yt-chip-cloud-chip-renderer');
newChip.setAttribute('class', 'style-scope yt-chip-cloud-renderer');
newChip.setAttribute('chip-style', 'STYLE_HOME_FILTER');
newChip.setAttribute('data-custom-shorts-chip', 'true');

const chipShapeContainer = document.createElement('div');
chipShapeContainer.id = 'chip-shape-container';
chipShapeContainer.setAttribute('class', 'style-scope yt-chip-cloud-chip-renderer');

const chipShape = document.createElement('chip-shape');
chipShape.setAttribute('class', 'ytChipShapeHost');

const btn = document.createElement('button');
btn.setAttribute('class', 'ytChipShapeButtonReset');
btn.setAttribute('role', 'tab');
btn.setAttribute('aria-selected', 'false');

const chipDiv = document.createElement('div');
chipDiv.setAttribute('class', 'ytChipShapeChip ytChipShapeInactive ytChipShapeOnlyTextPadding');

const textDiv = document.createElement('div');
textDiv.textContent = 'Shorts only';

chipDiv.appendChild(textDiv);
btn.appendChild(chipDiv);
chipShape.appendChild(btn);
chipShapeContainer.appendChild(chipShape);
newChip.appendChild(chipShapeContainer);

unwatchedChip.parentNode.insertBefore(newChip, unwatchedChip.nextElementSibling);

// Add click handler for the Shorts chip
btn.addEventListener('click', function() {
  const allChips = document.querySelectorAll('yt-chip-cloud-chip-renderer');

  // Toggle: check if any grid-shelf is visible (meaning shorts mode might be off)
  const gridShelves = document.querySelectorAll('grid-shelf-view-model');
  const videoRenderers = document.querySelectorAll('ytd-video-renderer, ytd-search-pyv-renderer, ytd-shelf-renderer.ytd-item-section-renderer, ytd-horizontal-card-list-renderer');

  let shortsActive = false;
  for (let v of videoRenderers) {
    if (v.style.display !== 'none') {
      shortsActive = false;
      break;
    }
  }
  if (videoRenderers.length === 0 || (!shortsActive)) {
    // Check if already in shorts mode
    const firstVideoVisible = Array.from(videoRenderers).some(v => v.style.display !== 'none');
    if (!firstVideoVisible) {
      shortsActive = true;
    }
  }

  // Deactivate all chips visually
  allChips.forEach(c => {
    c.classList.remove('iron-selected');
    const b = c.querySelector('button');
    if (b) b.setAttribute('aria-selected', 'false');
    const cd = c.querySelector('.ytChipShapeChip');
    if (cd) {
      cd.classList.remove('ytChipShapeActive');
      cd.classList.add('ytChipShapeInactive');
    }
  });

  // Activate this chip
  newChip.classList.add('iron-selected');
  btn.setAttribute('aria-selected', 'true');
  const activeChipDiv = newChip.querySelector('.ytChipShapeChip');
  if (activeChipDiv) {
    activeChipDiv.classList.remove('ytChipShapeInactive');
    activeChipDiv.classList.add('ytChipShapeActive');
  }

  // Hide non-Shorts content, show grid-shelf-view-model elements
  videoRenderers.forEach(v => { v.style.display = 'none'; });
  gridShelves.forEach(g => { g.style.display = ''; });

  // Move all grid shelves to top of contents
  const contentsDiv = document.querySelector('ytd-item-section-renderer > #contents');
  if (contentsDiv) {
    gridShelves.forEach(g => {
      contentsDiv.insertBefore(g, contentsDiv.firstChild);
    });
  }
}, true);

// Also update the "All" chip to restore normal view
const allChip = document.querySelector('yt-chip-cloud-chip-renderer.iron-selected button, yt-chip-cloud-chip-renderer:first-child button');
if (allChip && allChip !== btn) {
  allChip.addEventListener('click', function() {
    const videoRenderers = document.querySelectorAll('ytd-video-renderer, ytd-search-pyv-renderer, ytd-shelf-renderer.ytd-item-section-renderer, ytd-horizontal-card-list-renderer');
    const gridShelves = document.querySelectorAll('grid-shelf-view-model');

    // Show everything
    videoRenderers.forEach(v => { v.style.display = ''; });
    gridShelves.forEach(g => { g.style.display = ''; });
  }, true);
}

// Move all grid-shelf-view-model (Shorts shelves) to the top of the contents area
const contentsDiv = document.querySelector('ytd-item-section-renderer > #contents');
if (!contentsDiv) return;

// Only move if not already at the correct position
// Check if this element is already before any non-grid-shelf elements
let prevSibling = element.previousElementSibling;
while (prevSibling) {
  if (!prevSibling.classList.contains('ytGridShelfViewModelHost')) {
    // There's a non-Shorts element before us, move to top
    contentsDiv.insertBefore(element, contentsDiv.firstChild);
    break;
  }
  prevSibling = prevSibling.previousElementSibling;
}

// Move all grid-shelf-view-model elements (Shorts) to the very top
const contents = element;
if (!contents) return;

const gridShelves = Array.from(contents.querySelectorAll('grid-shelf-view-model.ytGridShelfViewModelHost'));
if (gridShelves.length === 0) return;

// Check if already at the top - first child should be a grid shelf
const firstChild = contents.firstElementChild;
if (firstChild && firstChild.classList.contains('ytGridShelfViewModelHost')) return;

// Move each grid shelf to the front, in their original order
gridShelves.forEach(function(shelf) {
  contents.insertBefore(shelf, contents.firstChild);
});

// Add "Shorts only" chip after "Unwatched" (the 2nd chip)
if (element.getAttribute('data-shorts-chip-added') === 'true') return;

const chips = Array.from(element.querySelectorAll('yt-chip-cloud-chip-renderer'));
if (chips.length < 2) return;

// Check if already added
for (let i = 0; i < chips.length; i++) {
  const textDiv = chips[i].querySelector('button > .ytChipShapeChip > div');
  if (textDiv && textDiv.textContent.trim() === 'Shorts only') return;
}

const unwatchedChip = chips[1]; // "Unwatched" is the 2nd chip

const newChip = document.createElement('yt-chip-cloud-chip-renderer');
newChip.setAttribute('chip-style', 'STYLE_HOME_FILTER');

const container = document.createElement('div');
container.id = 'chip-shape-container';

const chipShape = document.createElement('chip-shape');
chipShape.setAttribute('class', 'ytChipShapeHost');

const button = document.createElement('button');
button.setAttribute('class', 'ytChipShapeButtonReset');
button.setAttribute('role', 'tab');
button.setAttribute('aria-selected', 'false');

const chipDiv = document.createElement('div');
chipDiv.setAttribute('class', 'ytChipShapeChip ytChipShapeInactive ytChipShapeOnlyTextPadding');

const textDiv = document.createElement('div');
textDiv.textContent = 'Shorts only';

chipDiv.appendChild(textDiv);
button.appendChild(chipDiv);
chipShape.appendChild(button);
container.appendChild(chipShape);
newChip.appendChild(container);

element.insertBefore(newChip, unwatchedChip.nextSibling);
element.setAttribute('data-shorts-chip-added', 'true');

// Click handler for Shorts only chip
button.addEventListener('click', function() {
  var allChips = element.querySelectorAll('yt-chip-cloud-chip-renderer');
  var gridShelves = document.querySelectorAll('grid-shelf-view-model.ytGridShelfViewModelHost');
  var otherContent = document.querySelectorAll('ytd-video-renderer, ytd-search-pyv-renderer, ytd-shelf-renderer.ytd-item-section-renderer, ytd-horizontal-card-list-renderer');

  // Deactivate all chips
  for (var i = 0; i < allChips.length; i++) {
    allChips[i].classList.remove('iron-selected');
    var b = allChips[i].querySelector('button');
    if (b) b.setAttribute('aria-selected', 'false');
    var cd = allChips[i].querySelector('.ytChipShapeChip');
    if (cd) {
      cd.classList.remove('ytChipShapeActive');
      cd.classList.add('ytChipShapeInactive');
    }
  }

  // Activate Shorts only chip
  newChip.classList.add('iron-selected');
  button.setAttribute('aria-selected', 'true');
  var activeDiv = newChip.querySelector('.ytChipShapeChip');
  if (activeDiv) {
    activeDiv.classList.remove('ytChipShapeInactive');
    activeDiv.classList.add('ytChipShapeActive');
  }

  // Hide non-Shorts content
  for (var j = 0; j < otherContent.length; j++) {
    otherContent[j].style.display = 'none';
  }
  for (var k = 0; k < gridShelves.length; k++) {
    gridShelves[k].style.display = '';
  }
}, true);

// Also update existing chips to restore normal view when clicked
for (var m = 0; m < allChips.length; m++) {
  if (allChips[m] === newChip) continue;
  var existingBtn = allChips[m].querySelector('button');
  if (!existingBtn) continue;
  existingBtn.addEventListener('click', function() {
    var otherContent2 = document.querySelectorAll('ytd-video-renderer, ytd-search-pyv-renderer, ytd-shelf-renderer.ytd-item-section-renderer, ytd-horizontal-card-list-renderer');
    var gridShelves2 = document.querySelectorAll('grid-shelf-view-model.ytGridShelfViewModelHost');
    for (var p = 0; p < otherContent2.length; p++) {
      otherContent2[p].style.display = '';
    }
    for (var q = 0; q < gridShelves2.length; q++) {
      gridShelves2[q].style.display = '';
    }
  }, true);
}
